def shortest_path(graph, source, target):
    # Initialize the distance and path dictionaries
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Priority queue will be used to store (distance, node) pairs
    from heapq import heappush, heappop
    priority_queue = [(distances[source], source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we reached the target, we can stop the search
        if current_node == target:
            break

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a new shortest path is found, update the distance and path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = [current_node, neighbor]
                heappush(priority_queue, (distance, neighbor))

            # If a better path is found, update the distance and path
            elif distance == distances[neighbor]:
                path[neighbor] = [current_node, neighbor]
                heappush(priority_queue, (distance, neighbor))

    # If a path to the target was found, reconstruct the path
    if path[target] is not None:
        path_to_target = [target]
        current_node = target
        while current_node != source:
            current_node = path[current_node][0]
            path_to_target.append(current_node)
        path_to_target.reverse()
        return (distances[target], path_to_target)
    else:
        # If there is no path, return infinity and None
        return (float('inf'), None)

