    def dijkstra(graph, source):
        # Priority queue to hold (distance, node) pairs
        priority_queue = [(0, source)]
        # Dictionary to hold the shortest path to each node
        distances = {node: float('inf') for node in graph}
        distances[source] = 0

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == target:
                # Reached the target node, return the shortest path
                return distances[target]

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        # If the target node is unreachable
        return float('inf')

    # Calculate the shortest path
    distance = dijkstra(graph, source)
    # Find the path itself
    path = [target]
    current_node = target
    while current_node != source:
        for neighbor, _ in graph[current_node]:
            if distances[neighbor] == distances[current_node] - 1:
                path.append(neighbor)
                current_node = neighbor
                break

    # Reconstruct the path
    path.reverse()
    return (distance, path) if distance != float('inf') else (float('inf'), None)

