def shortest_path(graph, source, target):
    # Initialize the distances dictionary
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the path dictionary
    previous_nodes = {node: None for node in graph}

    # Set of all visited nodes
    visited = set()

    while target not in visited:
        # Visit the node with the minimum distance
        current_min_node = None
        for node in distances:
            if node not in visited and (current_min_node is None or distances[node] < distances[current_min_node]):
                current_min_node = node

        visited.add(current_min_node)

        # Visit neighbors
        for neighbor, weight in graph[current_min_node]:
            if distances[neighbor] > distances[current_min_node] + weight:
                distances[neighbor] = distances[current_min_node] + weight
                previous_nodes[neighbor] = current_min_node

    # Reconstruct the shortest path
    path = []
    current_node = target
    while current_node is not None:
        path.append(current_node)
        previous_node = previous_nodes[current_node]
        current_node = previous_node

    # If the target is not reachable, path will be empty
    path = path[::-1]  # Reverse the path

    # If the target is not reachable, distances[target] will still be infinity
    if distances[target] != float('inf'):
        return (distances[target], path)
    else:
        return (float('inf'), None)

