import heapq

def shortest_path(graph, source, target):
    # Initialize the distance dictionary and the priority queue
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    priority_queue = [(0, source)]

    # Initialize the path dictionary to keep track of the shortest paths
    paths = {source: []}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we have reached the target, we have found the shortest path
        if current_node == target:
            return (current_distance, paths[current_node])

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Check if a shorter path to the neighbor was found
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = paths[current_node] + [current_node]
                heapq.heappush(priority_queue, (distance, neighbor))

    # If we cannot reach the target, return infinity and None
    return (float("inf"), None)

