    # Helper function to perform Dijkstra's algorithm
    def dijkstra(graph, start, end):
        priority_queue = []
        shortest_distances = {node: float('inf') for node in graph}
        shortest_distances[start] = 0
        heapq.heappush(priority_queue, (0, start))

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == end:
                return current_distance

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < shortest_distances[neighbor]:
                    shortest_distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return float('inf')

    distance = dijkstra(graph, source, target)

    # If target is not reachable from source, return the infinity distance and None
    if distance == float('inf'):
        return float('inf'), None

    # Function to reconstruct the path from the distances
    def reconstruct_path(graph, start, end, distances):
        path = []
        current_node = end
        while current_node != start:
            for neighbor, _ in graph[current_node]:
                if distances[start][current_node] == distances[start][neighbor] + graph[neighbor][current_node]:
                    path.append(neighbor)
                    current_node = neighbor
                    break
        path.append(start)
        path.reverse()
        return path

    return distance, reconstruct_path(graph, source, target, distances=shortest_distances)

