def shortest_path(graph, source, target):
    from heapq import heappop, heappush

    # Priority queue for Dijkstra's algorithm
    queue = [(0, source, [])]

    # Dictionary to store the shortest distance to a node and the path to it
    distances = {source: (0, [])}
    visited = set()

    while queue:
        (cost, current, path) = heappop(queue)

        if current in visited:
            continue
        visited.add(current)

        # Add current node to the path
        path = path + [current]

        # If target is reached, return the distance and path
        if current == target:
            return (cost, path)

        for (neighbor, weight) in graph.get(current, []):
            new_cost = cost + weight
            if neighbor not in distances or new_cost < distances[neighbor][0]:
                distances[neighbor] = (new_cost, path[:])
                heappush(queue, (new_cost, neighbor, path[:]))

    # If target node is not reachable from source node, return infinity and None
    return (float("inf"), None)

