def shortest_path(graph, source, target):
    # Priority queue to store (distance, node) pairs
    queue = [(0, source)]
    # Dictionary to store the shortest distance to each node from the source
    distances = {node: float('inf') for node in graph}
    # Shortest path from source to target
    path = None
    # Dictionary to store the shortest path to each node from the source
    previous = {node: None for node in graph}
    distances[source] = 0

    while queue:
        current_distance, current_node = heapq.heappop(queue)
        # If we found a shorter path to the current node, update the previous nodes
        if current_distance > distances[current_node]:
            continue
        # If we reached the target node, reconstruct the path
        if current_node == target:
            path = reconstruct_path(previous, current_node)
            return (distances[target], path)

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            # If a shorter path is found, update the distance and the path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                # Add the neighbor to the queue with the updated distance
                heapq.heappush(queue, (distance, neighbor))

    # If the target node is unreachable, return infinity and None
    return (float('inf'), None)

def reconstruct_path(previous, current):
    path = [current]
    while previous[current] is not None:
        current = previous[current]
        path.append(current)
    path.reverse()
    return path
